): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const offer = await ownershipHandoverRepo.findPending(orgId);
  return offer !== null && isOpen(offer, new Date()) ? offer : null;
}

async function loadOrg(orgId: OrgId): Promise<Organization> {
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/**
 * Offering and withdrawing belong to the recorded owner alone. The owner role
 * is checked first, so the matrix still decides who may hold the action at all;
 * a second owner passes that check and is refused here.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:transfer_ownership", orgResource(org.id));
  if (actor.userId === org.ownerId) return;

  throw new PermissionDeniedError("org:transfer_ownership", {
    action: "org:transfer_ownership",
    allowed: false,
    resourceKind: "organization",
    reason: "denied_not_recorded_owner",
  });
}

/** An offer is open until its expiry instant; from that instant on it has lapsed. */
function isOpen(offer: OwnershipHandover, now: Date): boolean {
  return Date.parse(offer.expiresAt) > now.getTime();
}

/**
 * The open offer the actor may act on. Anyone other than the offered member is
 * refused with `nothing_pending`, as is everyone when no offer is pending. The
 * offered member is refused with `expired` once the offer has lapsed. Nothing
 * is written on any refusal.
 */
async function recipientOffer(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const offer = await ownershipHandoverRepo.findPending(orgId);
  if (offer === null || offer.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (!isOpen(offer, now)) {
    throw new OwnershipHandoverError("expired");
  }
  return offer;
}

