/**
 * Offers the workspace to another active member. Only the recorded owner may
 * offer, and a second offer is refused while one is still open.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertRecordedOwner(actor, await loadOrg(orgId));

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (target?.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const handover = await ownershipHandoverRepo.openHandover({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + OWNERSHIP_OFFER_TTL_MS)),
  });
  if (handover === null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership was offered to you",
    body: `The offer lapses at ${handover.expiresAt}`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. They become the recorded owner
 * holding the owner role, and the previous owner steps down to admin if they
 * still hold the owner role. The incoming owner is promoted before the previous
 * one is demoted, so the workspace has an owner at every step.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await recipientOffer(actor, orgId, new Date());
  const previousOwnerId = (await loadOrg(orgId)).ownerId;

  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  await orgRepo.updateOwner(orgId, actor.userId);

  const previous = await memberRepo.findMember(orgId, previousOwnerId);
  if (previous?.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: previous.role,
      to: demoted.role,
    });
  }

  await ownershipHandoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: previousOwnerId,
    toUserId: actor.userId,
  });

  return loadOrg(orgId);
}

/** The offered member turns the offer down; nothing else changes. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const offer = await recipientOffer(actor, orgId, now);

  return ownershipHandoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(now),
  );
}

/** The recorded owner withdraws an open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertRecordedOwner(actor, await loadOrg(orgId));

  const now = new Date();
