/**
 * Ownership handover: offers, acceptance, refusals, lapse and the consequences of accepting.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import {
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as memberService from "@/server/services/member-service";
import * as organizationService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OwnershipHandover } from "@/types/organization";

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** The refusal reason an attempt fails with; any other failure is rethrown. */
async function refusalOf(attempt: Promise<unknown>): Promise<string> {
  try {
    await attempt;
  } catch (error) {
    if (error instanceof OwnershipHandoverError) return error.reason;
    throw error;
  }
  throw new Error("expected the attempt to be refused");
}

async function actorFor(tenant: Tenant, userId: UserId): Promise<Actor> {
  const actor = await memberService.resolveActor(userId, tenant.org.id);
  if (!actor) throw new Error("fixture member missing");
  return actor;
}

async function memberOf(tenant: Tenant, userId: UserId) {
  const member = await memberRepo.findMember(tenant.org.id, userId);
  if (!member) throw new Error("fixture member missing");
  return member;
}

async function promote(tenant: Tenant, userId: UserId): Promise<void> {
  const member = await memberOf(tenant, userId);
  await memberService.updateMemberRole(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: member.id,
    role: "owner",
  });
}

async function ownershipAlerts(orgId: OrgId, recipientId: UserId) {
  const page = await notificationRepo.listNotifications({
    orgId,
    recipientId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  return page.items.filter((item) => item.kind === "ownership_handover");
}

describe("services/organization-service ownership handover", () => {
  it("records an open offer for an active member and alerts only that member", async () => {
    const tenant = await createTenant("handover-offer");

    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(SEVEN_DAYS_MS);

    expect(await ownershipAlerts(tenant.org.id, tenant.userIds.viewer)).toHaveLength(1);
    expect(await ownershipAlerts(tenant.org.id, tenant.userIds.admin)).toHaveLength(0);
    expect(await ownershipAlerts(tenant.org.id, tenant.userIds.member)).toHaveLength(0);
  });

  it("refuses a second offer while one is open", async () => {
    const tenant = await createTenant("handover-pending");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    expect(
      await refusalOf(
        organizationService.initiateOwnershipHandover(
          tenant.actors.owner,
          tenant.org.id,
          tenant.userIds.admin,
        ),
      ),
    ).toBe("pending_exists");
  });

  it("lets only the recorded owner offer or withdraw, even when another member holds the owner role", async () => {
    const tenant = await createTenant("handover-recorded");
    await promote(tenant, tenant.userIds.admin);
    const secondOwner = await actorFor(tenant, tenant.userIds.admin);

    await expect(
      organizationService.initiateOwnershipHandover(
        secondOwner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    await expect(
      organizationService.cancelOwnershipHandover(secondOwner, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an offer to the owner, a member of another workspace, an unknown user or a removed member", async () => {
    const tenant = await createTenant("handover-targets");
    const outsider = await createTenant("handover-outsider");

    expect(
      await refusalOf(
        organizationService.initiateOwnershipHandover(
          tenant.actors.owner,
          tenant.org.id,
          tenant.userIds.owner,
        ),
      ),
    ).toBe("self");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        outsider.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        "usr_nobody" as UserId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, tenant.userIds.viewer)).id,
    });

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("shows the open offer to every member, and clears it once withdrawn", async () => {
    const tenant = await createTenant("handover-withdraw");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    for (const actor of [tenant.actors.viewer, tenant.actors.member, tenant.actors.owner]) {
      await expect(
        organizationService.getPendingOwnershipHandover(actor, tenant.org.id),
      ).resolves.toMatchObject({ toUserId: tenant.userIds.viewer, status: "pending" });
    }

    const withdrawn = await organizationService.cancelOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(withdrawn).toMatchObject({ status: "canceled" });
    expect(withdrawn.resolvedAt).toEqual(expect.any(String));

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    expect(
      await refusalOf(organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)),
    ).toBe("nothing_pending");
  });

  it("lets only the offered member decline, and a declined workspace can be offered again", async () => {
    const tenant = await createTenant("handover-decline");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    expect(
      await refusalOf(organizationService.declineOwnershipHandover(tenant.actors.admin, tenant.org.id)),
    ).toBe("nothing_pending");
    expect(
      await refusalOf(organizationService.declineOwnershipHandover(tenant.actors.owner, tenant.org.id)),
    ).toBe("nothing_pending");

    const declined = await organizationService.declineOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(declined).toMatchObject({ status: "declined" });
    expect(declined.resolvedAt).toEqual(expect.any(String));

    expect(
      await refusalOf(organizationService.declineOwnershipHandover(tenant.actors.viewer, tenant.org.id)),
    ).toBe("nothing_pending");

    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).resolves.toMatchObject({ toUserId: tenant.userIds.member, status: "pending" });
  });

  it("hands the workspace to a viewer who accepts, and steps the previous owner down to admin", async () => {
    const tenant = await createTenant("handover-accept");
    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    const acceptor = await actorFor(tenant, tenant.userIds.viewer);
    const updated = await organizationService.acceptOwnershipHandover(acceptor, tenant.org.id);

    expect(updated.ownerId).toBe(tenant.userIds.viewer);
    expect((await memberOf(tenant, tenant.userIds.viewer)).role).toBe("owner");
    expect((await memberOf(tenant, tenant.userIds.owner)).role).toBe("admin");

    expect(roleChanges).toMatchObject([
      { orgId: tenant.org.id, actorId: tenant.userIds.viewer, from: "viewer", to: "owner" },
      { orgId: tenant.org.id, actorId: tenant.userIds.viewer, from: "owner", to: "admin" },
    ]);
    expect(transfers).toMatchObject([
      {
        orgId: tenant.org.id,
        actorId: tenant.userIds.viewer,
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.viewer,
      },
    ]);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    expect(
      page.items.some(
        (event) =>
          event.action === "organization.ownership_transferred" &&
          event.subjectKind === "organization" &&
          event.subjectId === tenant.org.id &&
          event.metadata.fromUserId === tenant.userIds.owner &&
          event.metadata.toUserId === tenant.userIds.viewer,
      ),
    ).toBe(true);

    const previousOwner = await actorFor(tenant, tenant.userIds.owner);
    const newOwner = await actorFor(tenant, tenant.userIds.viewer);
    expect(can(previousOwner, "org:manage_billing", { kind: "billing", orgId: tenant.org.id })).toBe(false);
    expect(can(newOwner, "org:manage_billing", { kind: "billing", orgId: tenant.org.id })).toBe(true);

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    expect(
      await refusalOf(organizationService.acceptOwnershipHandover(acceptor, tenant.org.id)),
    ).toBe("nothing_pending");
  });

  it("lets the new owner remove the previous owner, now an admin, like any other admin", async () => {
    const tenant = await createTenant("handover-remove-previous");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );

    const removed = await memberService.removeMember(
      await actorFor(tenant, tenant.userIds.admin),
      { orgId: tenant.org.id, memberId: (await memberOf(tenant, tenant.userIds.owner)).id },
    );
    expect(removed.userId).toBe(tenant.userIds.owner);
  });

  it("changes only the previous owner's role when the acceptor already holds the owner role", async () => {
    const tenant = await createTenant("handover-co-owner");
    await promote(tenant, tenant.userIds.admin);
    const roleChanges = capture("member.role_changed");

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.admin),
      tenant.org.id,
    );

    expect(roleChanges).toMatchObject([
      {
        actorId: tenant.userIds.admin,
        memberId: (await memberOf(tenant, tenant.userIds.owner)).id,
        from: "owner",
        to: "admin",
      },
    ]);
    expect((await memberOf(tenant, tenant.userIds.admin)).role).toBe("owner");
  });

  it("leaves the previous owner's role alone when it has already changed", async () => {
    const tenant = await createTenant("handover-stepped");
    await promote(tenant, tenant.userIds.admin);

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    // The other owner demotes the recorded owner before the offer is taken up.
    await memberService.updateMemberRole(await actorFor(tenant, tenant.userIds.admin), {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, tenant.userIds.owner)).id,
      role: "member",
    });

    const roleChanges = capture("member.role_changed");
    await organizationService.acceptOwnershipHandover(
      await actorFor(tenant, tenant.userIds.viewer),
      tenant.org.id,
    );

    expect((await memberOf(tenant, tenant.userIds.owner)).role).toBe("member");
    expect(roleChanges).toMatchObject([{ from: "viewer", to: "owner" }]);
  });

  it("lapses seven days after it was made, and acting on it from then on changes nothing", async () => {
    const tenant = await createTenant("handover-lapse");
    const madeAt = new Date("2026-10-01T09:00:00.000Z");

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(madeAt);
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    vi.setSystemTime(new Date(madeAt.getTime() + SEVEN_DAYS_MS - 1));
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ status: "pending" });

    vi.setSystemTime(new Date(madeAt.getTime() + SEVEN_DAYS_MS));
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();

    const acceptor = await actorFor(tenant, tenant.userIds.viewer);
    expect(
      await refusalOf(organizationService.acceptOwnershipHandover(acceptor, tenant.org.id)),
    ).toBe("expired");
    expect(
      await refusalOf(organizationService.declineOwnershipHandover(acceptor, tenant.org.id)),
    ).toBe("expired");
    expect(
      await refusalOf(organizationService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id)),
    ).toBe("nothing_pending");
    expect(
      await refusalOf(organizationService.cancelOwnershipHandover(tenant.actors.owner, tenant.org.id)),
    ).toBe("nothing_pending");

    expect((await memberOf(tenant, tenant.userIds.viewer)).role).toBe("viewer");
    expect((await memberOf(tenant, tenant.userIds.owner)).role).toBe("owner");

    const replacement: OwnershipHandover = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(replacement).toMatchObject({ toUserId: tenant.userIds.admin, status: "pending" });
  });

  it("withdraws the offer when the offered member leaves the workspace", async () => {
    const tenant = await createTenant("handover-offered-removed");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, tenant.userIds.admin)).id,
    });

    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
  });

  it("withdraws the offer when the offering owner leaves while another owner remains", async () => {
    const tenant = await createTenant("handover-offerer-removed");
    await promote(tenant, tenant.userIds.admin);
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    const remainingOwner = await actorFor(tenant, tenant.userIds.admin);
    await memberService.removeMember(remainingOwner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, tenant.userIds.owner)).id,
    });

    await expect(
      organizationService.getPendingOwnershipHandover(remainingOwner, tenant.org.id),
    ).resolves.toBeNull();
  });

  it("refuses another workspace's id on every operation, and keeps offers invisible across workspaces", async () => {
    const tenant = await createTenant("handover-scope-a");
    const other = await createTenant("handover-scope-b");
    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.viewer,
    );

    const foreign = other.org.id;
    await expect(
      organizationService.initiateOwnershipHandover(tenant.actors.owner, foreign, other.userIds.viewer),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.viewer, foreign),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.declineOwnershipHandover(tenant.actors.viewer, foreign),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.cancelOwnershipHandover(tenant.actors.owner, foreign),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      organizationService.getPendingOwnershipHandover(tenant.actors.owner, foreign),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      organizationService.getPendingOwnershipHandover(other.actors.owner, other.org.id),
    ).resolves.toBeNull();
  });
});

