    const acceptor = await actorFor(tenant, tenant.userIds.viewer);
    const updated = await organizationService.acceptOwnershipHandover(acceptor, tenant.org.id);

    expect(updated.ownerId).toBe(tenant.userIds.viewer);
    expect((await memberOf(tenant, tenant.userIds.viewer)).role).toBe("owner");
    expect((await memberOf(tenant, tenant.userIds.owner)).role).toBe("admin");

    expect(roleChanges).toMatchObject([
