/**
 * Ownership offers. A workspace holds at most one open offer; an offer that has
 * lapsed keeps its `pending` row until the next offer records it as expired.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq, gt, or, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

export type ResolvedOwnershipHandoverStatus = Exclude<
  OwnershipHandoverStatus,
  "pending"
>;

export interface NewOwnershipHandover {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}

/** The latest offer still marked pending: open, or lapsed but not yet recorded as such. */
export async function findPending(orgId: OrgId): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Opens an offer unless one is still open at `createdAt`. Anything left pending
 * has lapsed by then, so it is recorded as expired before the new row goes in.
 * Nothing here awaits, so the check and the insert cannot interleave with a
 * second offer on the same workspace.
 */
export async function openHandover(
  input: NewOwnershipHandover,
): Promise<OwnershipHandover | null> {
  const db = getDb();
  const orgScope = orgPredicate(ownershipHandovers.orgId, input.orgId);

  const open = db
    .select({ id: ownershipHandovers.id })
    .from(ownershipHandovers)
    .where(
      and(
        orgScope,
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, input.createdAt),
      ),
    )
    .get();
  if (open) return null;

  db.update(ownershipHandovers)
    .set({
      status: "expired",
      resolvedAt: sql`${ownershipHandovers.expiresAt}`,
      updatedAt: input.createdAt,
    })
    .where(and(orgScope, eq(ownershipHandovers.status, "pending")))
    .run();

  const row = db
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      resolvedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** Moves an offer out of `pending`, stamping the instant it was resolved. */
export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: ResolvedOwnershipHandoverStatus,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, id),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

/**
 * Withdraws every open offer that names `userId` on either side, for when that
 * member leaves the workspace. Lapsed offers are no longer open and are left alone.
 */
export async function withdrawOpenInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
